import React from "react";
import { ShoppingBag, Menu, X, Moon, Sun } from "lucide-react";
import JewelArt from "./JewelArt";
import { COLORS, FONT_DISPLAY, THEME_MODES } from "../constants/theme";

export default function Nav({
  scrolled,
  menuOpen,
  setMenuOpen,
  cartOpen,
  setCartOpen,
  cartCount,
  bump,
  scrollTo,
  setFilter,
  themeMode,
  toggleTheme,
}) {
  const navTextColor = scrolled ? COLORS.text : COLORS.textOnStrong;
  const nextThemeLabel = themeMode === THEME_MODES.DARK ? "light" : "dark";

  const handleMobileNav = (id) => {
    scrollTo(id);
    setMenuOpen(false);
  };

  return (
    <header
      style={{
        position: "fixed",
        top: 0,
        left: 0,
        right: 0,
        zIndex: 50,
        background: scrolled ? COLORS.surfaceBase : "transparent",
        borderBottom: scrolled ? `1px solid ${COLORS.border}` : "1px solid transparent",
        backdropFilter: "blur(18px)",
        WebkitBackdropFilter: "blur(18px)",
        transition: "background 0.3s ease, border-color 0.3s ease",
      }}
    >
      <div style={{ maxWidth: 1240, margin: "0 auto" }} className="flex items-center justify-between px-4 sm:px-6 md:px-10">
        <a
          href="#top"
          style={{
            fontFamily: FONT_DISPLAY,
            fontSize: 20,
            letterSpacing: "0.04em",
            color: navTextColor,
            display: "flex",
            alignItems: "center",
            gap: 8,
            padding: "16px 0",
          }}
        >
          <JewelArt type="ring" style={{ width: 22, height: 22 }} />
          Nyasa
        </a>

        <nav className="hidden md:flex items-center" style={{ gap: 32 }}>
          {["Rings", "Necklaces", "Earrings"].map((c) => (
            <button
              key={c}
              onClick={() => scrollTo("shop")}
              className="underline-grow"
              style={{
                background: "none",
                border: "none",
                fontSize: 14,
                letterSpacing: "0.03em",
                color: navTextColor,
              }}
            >
              {c}
            </button>
          ))}
          <button
            onClick={() => scrollTo("craft")}
            className="underline-grow"
            style={{ background: "none", border: "none", fontSize: 14, letterSpacing: "0.03em", color: navTextColor }}
          >
            The Craft
          </button>
          <button
            onClick={() => scrollTo("faq")}
            className="underline-grow"
            style={{ background: "none", border: "none", fontSize: 14, letterSpacing: "0.03em", color: navTextColor }}
          >
            FAQ
          </button>
        </nav>

        <div className="flex items-center" style={{ gap: 10 }}>
          <button
            onClick={toggleTheme}
            aria-label={`Switch to ${nextThemeLabel} theme`}
            title={`Switch to ${nextThemeLabel} theme`}
            style={{
              width: 40,
              height: 40,
              borderRadius: 999,
              border: `1px solid ${scrolled ? COLORS.border : COLORS.toggleBorder}`,
              background: scrolled ? COLORS.surfaceSoft : COLORS.toggleSurface,
              color: navTextColor,
              display: "inline-flex",
              alignItems: "center",
              justifyContent: "center",
              boxShadow: scrolled ? "none" : "0 8px 24px rgba(15, 23, 42, 0.12)",
              transition: "background 0.3s ease, border-color 0.3s ease, color 0.3s ease",
            }}
          >
            {themeMode === THEME_MODES.DARK ? <Sun size={18} strokeWidth={1.7} /> : <Moon size={18} strokeWidth={1.7} />}
          </button>
          <button
            onClick={() => setCartOpen(true)}
            aria-label="Open cart"
            style={{
              background: "none",
              border: "none",
              position: "relative",
              color: navTextColor,
              padding: 8,
            }}
          >
            <ShoppingBag size={20} strokeWidth={1.6} />
            {cartCount > 0 && (
              <span
                className={bump ? "cart-badge-bump" : ""}
                style={{
                  position: "absolute",
                  top: 2,
                  right: 2,
                  background: COLORS.rust,
                  color: COLORS.textOnStrong,
                  fontSize: 10,
                  width: 16,
                  height: 16,
                  borderRadius: "50%",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                }}
              >
                {cartCount}
              </span>
            )}
          </button>
          <button
            className="md:hidden"
            onClick={() => setMenuOpen((v) => !v)}
            aria-label="Toggle menu"
            aria-expanded={menuOpen}
            style={{ background: "none", border: "none", color: navTextColor, padding: 8, minHeight: 44 }}
          >
            {menuOpen ? <X size={22} strokeWidth={1.6} /> : <Menu size={22} strokeWidth={1.6} />}
          </button>
        </div>
      </div>

      {menuOpen && (
        <>
          <div
            className="md:hidden"
            onClick={() => setMenuOpen(false)}
            style={{
              position: "fixed",
              top: 0,
              left: 0,
              right: 0,
              bottom: 0,
              background: "rgba(0,0,0,0.35)",
              zIndex: 40,
            }}
          />
          <div
            className="md:hidden"
            style={{
              position: "absolute",
              top: "100%",
              left: 0,
              right: 0,
              zIndex: 50,
              background: COLORS.surfaceBase,
              borderTop: `1px solid ${COLORS.border}`,
              borderBottom: `1px solid ${COLORS.border}`,
              padding: "10px 16px 20px",
              boxShadow: "0 12px 24px rgba(0,0,0,0.18)",
            }}
          >
            {["Rings", "Necklaces", "Earrings"].map((c) => (
              <button
                key={c}
                onClick={() => handleMobileNav("shop")}
                style={{
                  display: "block",
                  width: "100%",
                  textAlign: "left",
                  padding: "12px 0",
                  background: "none",
                  border: "none",
                  fontSize: 16,
                  color: COLORS.text,
                }}
              >
                {c}
              </button>
            ))}
            <button
              onClick={() => handleMobileNav("craft")}
              style={{
                display: "block",
                width: "100%",
                textAlign: "left",
                padding: "12px 0",
                background: "none",
                border: "none",
                fontSize: 16,
                color: COLORS.text,
              }}
            >
              The Craft
            </button>
            <button
              onClick={() => handleMobileNav("faq")}
              style={{
                display: "block",
                width: "100%",
                textAlign: "left",
                padding: "12px 0",
                background: "none",
                border: "none",
                fontSize: 16,
                color: COLORS.text,
              }}
            >
              FAQ
            </button>
          </div>
        </>
      )}
    </header>
  );
}
